+package handler
+
+import (
+	"errors"
+	"net/http"
+
+	"example.com/relay/store"
+	"example.com/relay/validate"
+)
+
+// StatusError carries an explicit HTTP status with an error.
+type StatusError struct {
+	Err    error
+	Status int
+}
+
+func (e *StatusError) Error() string { return e.Err.Error() }
+
+// Unwrap lets errors.Is see through to the underlying error.
+func (e *StatusError) Unwrap() error { return e.Err }
+
+// errorMapping pairs a sentinel error with the status it should produce.
+type errorMapping struct {
+	sentinel error
+	status   int
+}
+
+// errorMappings is consulted in order; the first match wins.
+var errorMappings = []errorMapping{
+	{store.ErrNotFound, http.StatusNotFound},
+	{store.ErrBusy, http.StatusServiceUnavailable},
+	{validate.ErrInvalid, http.StatusUnprocessableEntity},
+}
+
+// statusFor resolves the HTTP status for err, defaulting to 500.
+func statusFor(err error) int {
+	var se *StatusError
+	if errors.As(err, &se) {
+		return se.Status
+	}
+	for _, m := range errorMappings {
+		if errors.Is(err, m.sentinel) {
+			return m.status
+		}
+	}
+	return http.StatusInternalServerError
+}
+
+// writeError writes err as a plain-text response with its mapped status.
+// Internal errors are not echoed to the client.
+func writeError(w http.ResponseWriter, err error) {
+	status := statusFor(err)
+	msg := err.Error()
+	if status == http.StatusInternalServerError {
+		msg = http.StatusText(status)
+	}
+	http.Error(w, msg, status)
+}
